// Agarrar la respuesta de Claude
const respuestaClaude = $input.first().json;

// El texto que devolvió Claude está en content[0].text
let textoIA = respuestaClaude.content[0].text;

// Limpiar por si viene con ```json ... ``` alrededor
textoIA = textoIA.replace(/```json/g, '').replace(/```/g, '').trim();

// Convertir el texto JSON en un objeto real
const datos = JSON.parse(textoIA);

// Extraer los tokens que consumió
const tokensInput = respuestaClaude.usage.input_tokens;
const tokensOutput = respuestaClaude.usage.output_tokens;

// Calcular el costo (precios de Claude Haiku 4.5 por millón de tokens)
const costoInput = (tokensInput / 1000000) * 1.00;   // USD 1.00 por millón input
const costoOutput = (tokensOutput / 1000000) * 5.00; // USD 5.00 por millón output
const costoTotal = costoInput + costoOutput;

// Devolver todo ordenado
return {
  tipo: datos.tipo,
  urgencia: datos.urgencia,
  respuesta: datos.respuesta,
  tokens_input: tokensInput,
  tokens_output: tokensOutput,
  costo_usd: costoTotal
};
